}

/* Step Circle Node */
.step-node-circle {
  width: 44px !important;
  height: 44px !important;
  min-height: 44px !important;
  border-radius: 50% !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-size: 18px !important;
  font-weight: 800 !important;
  position: relative !important;
  z-index: 2 !important;
  transition: all 0.25s ease !important;
  box-sizing: border-box !important;
  flex-shrink: 0 !important;
}

/* Completed Stage: Green with check icon */
.step-node-circle.node-completed {
  background: #10B981 !important;
  color: #FFFFFF !important;
  border: 3px solid #059669 !important;
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.35) !important;
}

/* Current Stage: Yellow/Orange active circle */
.step-node-circle.node-current {
  background: #F59E0B !important;
  color: #FFFFFF !important;
  border: 3px solid #D97706 !important;
  box-shadow: 0 0 0 5px rgba(245, 158, 11, 0.2), 0 4px 16px rgba(217, 119, 6, 0.4) !important;
  transform: scale(1.08) !important;
}

/* Pending Stage: Gray circle */
.step-node-circle.node-pending {
  background: #F8FAFC !important;
  color: #94A3B8 !important;
  border: 2.5px solid #CBD5E1 !important;
  font-size: 16px !important;
}

/* Rejected Stage: Red with cross */
.step-node-circle.node-rejected {
  background: #EF4444 !important;
  color: #FFFFFF !important;
  border: 3px solid #DC2626 !important;
  box-shadow: 0 0 0 5px rgba(239, 68, 68, 0.2), 0 4px 16px rgba(220, 38, 38, 0.4) !important;
  transform: scale(1.08) !important;
}

/* Vertical Connecting Line */
