/* =========================================================================
   SUPPRESS SERVICENOW SYSTEM LOG BANNERS & CROSS-SCOPE PRIVILEGE MESSAGES
   ========================================================================= */
.sp-notification,
.sp-notification-container,
div[uib-alert],
.header-alerts,
