}

.workspace-tab-pane {
  animation: fadeInPane 0.2s ease-in-out !important;
}

@keyframes fadeInPane {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

sp_widget.script:
(function () {
  /* =========================================================================
   * AEGIS SERVICE PORTAL WIDGET - SERVER SCRIPT
   * Target Instance: https://ltm-hck-2876-0029.lab.service-now.com
   * ========================================================================= */

  // Clear cross-scope and system session alerts
  try {
    gs.flushMessages();
  } catch (eFM) { }

  data.currentUser = {
    sys_id: gs.getUserID(),
    name: gs.getUserDisplayName(),
    user_name: gs.getUserName(),
    email: gs.getUser().getEmail(),
    isLoggedIn: gs.isLoggedIn(),
    roles: gs.getUser().getRoles()
  };

  // NOTE: Do NOT update sp_page / sp_widget from a public widget's server script.
  // Mark page "aegis" and widget "aegis-talent-platform" as Public ONCE manually
  // in ServiceNow (Service Portal > Pages / Widgets), not on every page load.

  data.jobs = [];
  data.interviews = [];
  data.applications = [];

  // =========================================================================
  // 1. FETCH PUBLISHED JOB REQUISITIONS (JR) ONLY (FOR CANDIDATES)
  // Strict requirement: Only published JRs appear to candidates!
  // =========================================================================
  var jdText = '';   // declared at function scope so it can never be 'not defined'
  var grJR = new GlideRecord('x_snc_aegis_job_requisition');
  // Query only published requisitions (case-resilient for ServiceNow choice values)
  var qPub = grJR.addQuery('status', 'PUBLISHED');
  qPub.addOrCondition('status', 'Published');
  qPub.addOrCondition('status', 'published');
  grJR.orderByDesc('sys_created_on');
  grJR.query();

  var colors = ['icon-purple', 'icon-orange', 'icon-pink', 'icon-teal', 'icon-purple', 'icon-orange'];
  var letters = ['A', 'C', 'P', 'D', 'Q', 'M'];
  var colorIdx = 0;

  while (grJR.next()) {
    try {
      var jrSysId = grJR.getUniqueValue();
      var jrNumber = grJR.getValue('number') || '';
      var title = grJR.getValue('role_title') || grJR.getValue('title') || grJR.getDisplayValue('role_title') || '';
      var dept = grJR.getDisplayValue('department') || 'Others';
      var loc = grJR.getDisplayValue('location') || 'Chennai';
      var headcount = grJR.getValue('headcount') || '';
      var exp = grJR.getDisplayValue('experience_level') || grJR.getValue('level') || '';
      var edu = grJR.getValue('education_qualification') || '';
      var skillsStr = grJR.getValue('required_skills') || grJR.getValue('nice_to_have_skills') || '';
      var skillsArr = skillsStr.split(',').map(function (s) { return s.trim(); }).filter(function (s) { return s; });

      // Look up JD text created by AI agent from x_snc_aegis_job_description
      jdText = '';

      // Tier 1: Match by direct Job Requisition sys_id
      var grJD = new GlideRecord('x_snc_aegis_job_description');
      grJD.addQuery('job_requisition', jrSysId);
      grJD.orderByDesc('version');
      grJD.query();
      if (grJD.next()) {
        jdText = grJD.getValue('jd_text') || grJD.getValue('description') || '';
      }

      // Tier 2: Match by Job Requisition number
      if (!jdText && jrNumber) {
        var grJD2 = new GlideRecord('x_snc_aegis_job_description');
        grJD2.addQuery('job_requisition.number', jrNumber);
        grJD2.orderByDesc('version');
        grJD2.query();
        if (grJD2.next()) {
          jdText = grJD2.getValue('jd_text') || grJD2.getValue('description') || '';
        }
      }

      // Tier 3: Match by Role Title inside jd_text (e.g. "# Senior Software Engineer") in case reference was left unlinked by Agent
      if (!jdText && title) {
        var grJD3 = new GlideRecord('x_snc_aegis_job_description');
        grJD3.addQuery('jd_text', 'CONTAINS', title);
        grJD3.orderByDesc('sys_created_on');
        grJD3.query();
        if (grJD3.next()) {
          jdText = grJD3.getValue('jd_text') || grJD3.getValue('description') || '';
        }
      }

      // Tier 4: Fallback to any recent non-empty agent-created JD text in the table
      if (!jdText) {
        var grJD4 = new GlideRecord('x_snc_aegis_job_description');
        grJD4.addNotNullQuery('jd_text');
        grJD4.orderByDesc('sys_created_on');
        grJD4.setLimit(1);
        grJD4.query();
        if (grJD4.next()) {
          jdText = grJD4.getValue('jd_text') || '';
        }
      }

      var overview = jdText || grJR.getValue('overview') || grJR.getValue('offerings') || grJR.getValue('additional_comments') || '';

      var deadline = grJR.getDisplayValue('application_deadline') ||
        grJR.getValue('application_deadline') ||
        grJR.getDisplayValue('deadline') ||
        grJR.getValue('deadline') ||
        grJR.getDisplayValue('target_hire_date') ||
        '';

      // Strict requirement: Check current date and time.
      // If deadline has passed, the job must NOT appear in the job listings page!
      var deadlineRaw = grJR.getValue('application_deadline') || grJR.getValue('deadline') || grJR.getValue('target_hire_date') || '';
      var isDeadlineExceeded = false;
      if (deadlineRaw) {
        try {
          var gdtDeadline = new GlideDateTime(deadlineRaw);
          var gdtNow = new GlideDateTime();
          if (gdtDeadline.getNumericValue() < gdtNow.getNumericValue()) {
            isDeadlineExceeded = true;
          }
        } catch (eDt) { }
      }
      if (!isDeadlineExceeded && deadline) {
        try {
          var dStr = String(deadline).trim();
          var mIso = dStr.match(/^(\d{4})-(\d{2})-(\d{2})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?)?/i);
          if (mIso) {
            var y = parseInt(mIso[1], 10);
            var mo = parseInt(mIso[2], 10);
            var d = parseInt(mIso[3], 10);
            var gdtIso = new GlideDateTime();
            gdtIso.setValue(y + '-' + (mo < 10 ? '0' + mo : mo) + '-' + (d < 10 ? '0' + d : d) + ' 23:59:59');
            if (gdtIso.getNumericValue() < new GlideDateTime().getNumericValue()) {
              isDeadlineExceeded = true;
            }
          } else {
            var monthsMap = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
            var mText = dStr.match(/(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})/);
            if (mText) {
              var dayNum = parseInt(mText[1], 10);
              var mNum = monthsMap[mText[2].toLowerCase()] || 10;
              var yNum = parseInt(mText[3], 10);
              var gdtTxt = new GlideDateTime();
              gdtTxt.setValue(yNum + '-' + (mNum < 10 ? '0' + mNum : mNum) + '-' + (dayNum < 10 ? '0' + dayNum : dayNum) + ' 23:59:59');
              if (gdtTxt.getNumericValue() < new GlideDateTime().getNumericValue()) {
                isDeadlineExceeded = true;
              }
            }
          }
        } catch (eDt2) { }
      }

      // If deadline exceeded current date and time, do NOT include in job listings page
      if (isDeadlineExceeded) {
        continue;
      }

      data.jobs.push({
        id: jrSysId,
        number: jrNumber,
        title: title,
        department: dept,
        location: loc,
        positions: headcount ? (headcount + ' Positions') : '',
        experience: exp,
        education: edu,
        skills: skillsArr,
        deadline: deadline,
        colorClass: colors[colorIdx % colors.length],
        letter: letters[colorIdx % letters.length],
        overview: overview,
        status: 'Published'
      });
      colorIdx++;
    } catch (eJobRow) {
      gs.error('AEGIS widget: skipped job row ' + grJR.getValue('number') + ' - ' + eJobRow);
    }
  }

  // Fallback demo published jobs - OFF by default so empty/broken data is visible.
  // Set to true ONLY for local demos.
  var ALLOW_DEMO_FALLBACK = false;
  if (ALLOW_DEMO_FALLBACK && data.jobs.length === 0) {
    data.jobs = [
      {
        id: "JOB-ENG-01",
        number: "JR000101",
        title: "Senior Software Engineer",
        department: "Engineering",
        location: "Chennai",
        positions: "3 Positions",
        experience: "SENIOR",
        education: "Bachelor's Degree",
        status: "Published",
        deadline: "25 Sep 2026",
        skills: ["Java", "Python", "Microservices architecture", "REST APIs", "SQL", "NoSQL databases"],
        colorClass: "icon-purple",
        letter: "S",
        overview: "# Senior Software Engineer\n\n**Department:** ENGINEERING  \n**Level:** SENIOR  \n**Employment Type:** FULL_TIME  \n**Location:** New York Office / Remote  \n**Openings:** 3  \n**Application Deadline:** 25 Sep 2026\n\n## About the Role\nWe are seeking a Senior Software Engineer to join our Engineering department. In this role, you will develop cloud-native applications and collaborate with cross-functional teams to deliver high-quality software solutions. You will also participate in code reviews and mentor junior engineers.\n\n## Responsibilities\n- Develop cloud-native applications using modern technologies and best practices\n- Collaborate with cross-functional teams to design and implement software solutions\n- Participate in code reviews to maintain code quality and share knowledge\n- Mentor junior engineers and provide technical guidance\n\n## Required Qualifications\n- Experience: 5 years of relevant software engineering experience\n- Education: Bachelor's degree in Computer Science or equivalent"
      },
      {
        id: "JOB-INFRA-01",
        number: "JR000102",
        title: "Cloud Engineer",
        department: "Infrastructure",
        location: "Bangalore",
        positions: "4 Positions",
        experience: "3 - 6 Years",
        education: "Bachelor's Degree",
        status: "Published",
        deadline: "28 Oct 2026",
        skills: ["AWS", "DevOps", "Linux", "Terraform", "Kubernetes"],
        colorClass: "icon-orange",
        letter: "C",
