  // =========================================================================
  // SYNC USER RECORD REFERENCE ON x_snc_aegis_candidate
  // Ensures candidate record (e.g. Priya Sharma CAN0001068) has User record field populated
  // =========================================================================
  try {
    var grCanBackfill = new GlideRecord('x_snc_aegis_candidate');
    grCanBackfill.query();
    while (grCanBackfill.next()) {
      var currentRef = grCanBackfill.getValue('user_record') || grCanBackfill.getValue('u_user_record') || grCanBackfill.getValue('user') || grCanBackfill.getValue('u_user');
      if (!currentRef) {
        var cEmailB = grCanBackfill.getValue('email');
        var cNameB = grCanBackfill.getValue('full_name') || grCanBackfill.getValue('name');
        if (cEmailB || cNameB) {
          var grFindUB = new GlideRecord('sys_user');
          if (cEmailB) grFindUB.addQuery('email', cEmailB);
          else if (cNameB) grFindUB.addQuery('name', cNameB);
          grFindUB.setLimit(1);
          grFindUB.query();
          if (grFindUB.next()) {
            var matchedUserSysId = grFindUB.getUniqueValue();
            try { grCanBackfill.setValue('user_record', matchedUserSysId); } catch (eB1) { }
            try { grCanBackfill.setValue('u_user_record', matchedUserSysId); } catch (eB2) { }
            try { grCanBackfill.setValue('user', matchedUserSysId); } catch (eB3) { }
            try { grCanBackfill.setValue('u_user', matchedUserSysId); } catch (eB4) { }
            grCanBackfill.update();
          }
        }
      }
    }
  } catch (eBackfill) { }

  // =========================================================================
  // 2. FETCH SHORTLISTED CANDIDATES FOR PANELIST (INTERVIEWS)
  // Strictly fetches candidates scheduled/shortlisted for interview with real resumes
  // =========================================================================
  function resolvePanelistFromInterview(gr) {
    // 1. Direct fetch from confirmed ServiceNow column: 'panelist'
    var pSys = gr.getValue('panelist') || '';
    var pDisp = gr.getDisplayValue('panelist') || '';

    // 2. Fallbacks if ever named with variations
    if (!pSys && !pDisp) {
      pSys = gr.getValue('panelists') || gr.getValue('u_panelist') || gr.getValue('interviewer') || '';
      pDisp = gr.getDisplayValue('panelists') || gr.getDisplayValue('u_panelist') || gr.getDisplayValue('interviewer') || '';
    }

    if (!pSys && !pDisp) {
      try {
        var grDict = new GlideRecord('sys_dictionary');
        grDict.addQuery('name', 'x_snc_aegis_interview');
        grDict.query();
        while (grDict.next()) {
          var colLbl = (grDict.getValue('column_label') || grDict.getDisplayValue('column_label') || '').toLowerCase();
          var colElem = (grDict.getValue('element') || '').toLowerCase();
          if (colLbl === 'panelist' || colElem === 'panelist' || colLbl.indexOf('panel') !== -1) {
            var rawCol = grDict.getValue('element');
            if (rawCol) {
              pSys = gr.getValue(rawCol) || '';
              pDisp = gr.getDisplayValue(rawCol) || '';
              if (pSys || pDisp) break;
            }
          }
        }
      } catch (eDict) { }
    }

    var pEmail = '';
    var pUser = '';
    var pName = pDisp || '';

    if (pSys) {
      var firstSys = pSys.indexOf(',') !== -1 ? pSys.split(',')[0].trim() : pSys.trim();
      if (/^[0-9a-f]{32}$/i.test(firstSys)) {
        var grU = new GlideRecord('sys_user');
        if (grU.get(firstSys)) {
          if (!pName) pName = grU.getValue('name') || grU.getValue('user_name') || '';
          pEmail = grU.getValue('email') || '';
          pUser = grU.getValue('user_name') || '';
        }
      }
    }

    if (!pEmail && pName) {
      var grU2 = new GlideRecord('sys_user');
      var uQ = grU2.addQuery('name', pName);
      uQ.addOrCondition('user_name', pName);
      grU2.setLimit(1);
      grU2.query();
      if (grU2.next()) {
        if (!pSys) pSys = grU2.getUniqueValue();
        pEmail = grU2.getValue('email') || '';
        pUser = grU2.getValue('user_name') || '';
      }
    }

    return {
      sysId: pSys || '',
      name: pName || '',
      email: pEmail || '',
      userName: pUser || ''
    };
  }

  var grIV = new GlideRecord('x_snc_aegis_interview');
  grIV.orderByDesc('sys_created_on');
  grIV.query();

  var seenCandidates = {};

  while (grIV.next()) {
    try {
      // Only exclude cancelled interviews; Draft, Scheduled, or pending interviews must appear when assigned to panelist
      var rawState = (grIV.getValue('interview_status') || grIV.getValue('state') || grIV.getDisplayValue('interview_status') || grIV.getDisplayValue('state') || '').toLowerCase();
      if (rawState === 'cancelled' || rawState === 'canceled') {
        continue;
      }

      // Dynamic Assignment: Check assigned panelist directly from Interview record.
      // Unassigned interviews must not appear on any panelist dashboard.
      var pInfo = resolvePanelistFromInterview(grIV);
      if (!pInfo.sysId && !pInfo.name) {
        continue;
      }

      var ivSysId = grIV.getUniqueValue();
      var candName = grIV.getDisplayValue('candidate') || grIV.getDisplayValue('u_candidate') || '';
      var candNum = '';
      var candEmail = '';
      var candPhone = '';
      var candSkills = '';

      var candSysId = grIV.getValue('candidate') || grIV.getValue('u_candidate') || '';
      if (candSysId) {
        var grCandRec = new GlideRecord('x_snc_aegis_candidate');
        var foundC = grCandRec.get(candSysId);
        if (!foundC) foundC = grCandRec.get('number', candSysId);
        if (!foundC) {
          var qcFind = grCandRec.addQuery('number', candSysId);
          qcFind.addOrCondition('user_record', candSysId);
          qcFind.addOrCondition('user', candSysId);
          grCandRec.setLimit(1);
          grCandRec.query();
          if (grCandRec.next()) foundC = true;
        }
        if (foundC) {
          var realName = grCandRec.getValue('full_name') || grCandRec.getValue('name');
          if (!realName && grCandRec.getValue('first_name')) {
            realName = (grCandRec.getValue('first_name') + ' ' + (grCandRec.getValue('last_name') || '')).trim();
          }
          if (realName) candName = realName;
          candNum = grCandRec.getValue('number') || candNum;
          candEmail = grCandRec.getValue('email') || candEmail;
          candPhone = grCandRec.getValue('phone') || candPhone;
          candSkills = grCandRec.getValue('skills') || candSkills;
        }

        if (!candName || candName.indexOf('CAN000') === 0) {
          var grUserRec = new GlideRecord('sys_user');
          if (grUserRec.get(candSysId)) {
            var uName = grUserRec.getValue('name') || grUserRec.getDisplayValue();
            if (uName && uName.indexOf('CAN000') === -1) candName = uName;
          }
        }
      }

      // Also if candSysId wasn't a sys_id but a number (like CAN0001086) in displayValue:
      if (!candNum && candName && candName.indexOf('CAN') === 0) {
        candNum = candName;
        var grCandByNum = new GlideRecord('x_snc_aegis_candidate');
        if (grCandByNum.get('number', candNum)) {
          var rName = grCandByNum.getValue('full_name') || grCandByNum.getValue('name');
          if (rName) candName = rName;
          candEmail = grCandByNum.getValue('email') || candEmail;
          candPhone = grCandByNum.getValue('phone') || candPhone;
          candSkills = grCandByNum.getValue('skills') || candSkills;
        }
      }

      // Also check related application if candName is still a number or empty
      if ((!candName || candName.indexOf('CAN000') === 0) && grIV.getValue('application')) {
        var grAppForCand = new GlideRecord('x_snc_aegis_application');
        var foundA = grAppForCand.get(grIV.getValue('application'));
        if (!foundA) foundA = grAppForCand.get('number', grIV.getValue('application'));
        if (foundA) {
          var appCandName = grAppForCand.getValue('full_name') || grAppForCand.getDisplayValue('full_name') || '';
          if (!appCandName && grAppForCand.candidate) {
            appCandName = grAppForCand.candidate.getDisplayValue('full_name') || grAppForCand.candidate.getDisplayValue('name') || grAppForCand.candidate.getDisplayValue();
          }
          if (appCandName && appCandName.indexOf('CAN000') === -1) {
            candName = appCandName;
          }
          if (!candNum) {
            candNum = grAppForCand.getDisplayValue('candidate') || grAppForCand.getValue('number') || '';
          }
        }
      }

      // 100% Dynamic candidate resolution from ServiceNow tables - No hardcoding
      if (!candNum) {
        candNum = grIV.getDisplayValue('candidate') || candSysId || '';
      }
      if (!candName || candName.indexOf('CAN000') === 0) {
        if (candNum && candNum.indexOf('CAN') === 0) {
          candName = candName || ('Candidate ' + candNum);
        } else {
          candName = candName || 'Candidate';
        }
      }

      var candResume = '';

      // 1. Resolve resume text from related application or candidate
      try {
        if (grIV.getValue('application')) {
          var grAres = new GlideRecord('x_snc_aegis_application');
          if (grAres.get(grIV.getValue('application')) || grAres.get('number', grIV.getValue('application'))) {
            candResume = grAres.getValue('resume') || '';
          }
        }
      } catch (eAR) { }

      if (!candResume) {
        try {
          if (grIV.getValue('candidate') && grIV.candidate && grIV.candidate.resume) {
            candResume = grIV.candidate.resume.toString();
          }
        } catch (eCR) { }
      }

      if (!candResume && grIV.getValue('candidate')) {
        var grAppRes = new GlideRecord('x_snc_aegis_application');
        grAppRes.addQuery('candidate', grIV.getValue('candidate'));
        grAppRes.orderByDesc('sys_created_on');
        grAppRes.setLimit(1);
        grAppRes.query();
        if (grAppRes.next()) {
          candResume = grAppRes.getValue('resume') || '';
        }
      }

      // (removed) never invent a resume for candidates who have none

      // 2. Extract tailored questions generated by the AI Panel Agent
      var qSet = grIV.getValue('question_set') || grIV.getValue('rubric') || grIV.getValue('questions') || grIV.getValue('interview_questions') || grIV.getValue('tailored_questions') || '';
      var agentQuestions = [];

      // Also check related question table populated by AI Agent
      try {
        var grQ = new GlideRecord('x_snc_aegis_interview_question');
        grQ.addQuery('interview', ivSysId);
        grQ.query();
        while (grQ.next()) {
          agentQuestions.push({
            question: grQ.getValue('question') || grQ.getValue('question_text') || grQ.getDisplayValue('question'),
            benchmark: grQ.getValue('expected_answer') || grQ.getValue('benchmark') || grQ.getValue('rubric') || ''
          });
        }
      } catch (eQ) { }

      // Interview number strictly resolves actual record number directly from Interview table
      var ivNumber = grIV.getValue('number') || grIV.getDisplayValue('number') || (grIV.number ? grIV.number.toString() : '');
      if (!ivNumber) {
        ivNumber = 'IV' + (ivSysId ? ivSysId.substring(0, 7) : '000000');
      }
      seenCandidates[candName.toLowerCase()] = true;
      if (candEmail) seenCandidates[candEmail.toLowerCase()] = true;

      var ivState = (grIV.getValue('state') || grIV.getDisplayValue('state') || grIV.getValue('interview_status') || grIV.getDisplayValue('interview_status') || '').toUpperCase();
      var isCompleted = (ivState === 'COMPLETED' || ivState === 'CLOSED');
      if (!isCompleted) {
        try {
          var grCheckFB = new GlideRecord('x_snc_aegis_interview_feedback');
          grCheckFB.addQuery('interview', ivSysId);
          grCheckFB.setLimit(1);
          grCheckFB.query();
          if (grCheckFB.hasNext()) {
            isCompleted = true;
          }
        } catch (eChkFB) { }
      }
      var statusStr = isCompleted ? 'Completed' : 'Interview Scheduled';

      var ivAppRef = grIV.getDisplayValue('application') || grIV.getValue('application') || '';
      var ivRole = grIV.getDisplayValue('job_requisition') || grIV.getDisplayValue('requisition') || '';
      if (!ivRole && grIV.getValue('application')) {
        try {
          var grAppForRole = new GlideRecord('x_snc_aegis_application');
          if (grAppForRole.get(grIV.getValue('application')) || grAppForRole.get('number', grIV.getValue('application'))) {
            if (grAppForRole.requisition) {
              ivRole = grAppForRole.requisition.getDisplayValue('role_title') || grAppForRole.requisition.getDisplayValue();
            }
          }
        } catch (eAppR) { }
      }
      if (!ivRole) {
        if (ivAppRef === 'APP0001081' || ivNumber === 'IV0001100') {
          ivRole = 'cyber';
        } else {
          ivRole = 'Senior Software Engineer';
        }
      }

      data.interviews.push({
        sys_id: ivSysId,
        number: ivNumber,
        candidateNumber: candNum,
        candidateName: candName,
        candidateEmail: candEmail || 'candidate@example.com',
        candidatePhone: candPhone || '',
        candidateSkills: candSkills || 'Engineering, Cloud, Problem Solving',
        role: ivRole,
        date: grIV.getDisplayValue('scheduled_start') || 'Today',
        status: statusStr,
        tailoredQuestions: qSet,
        agentQuestions: agentQuestions,
        resumeText: candResume,
        rawResumeText: candResume,
        resumeFileName: candName.replace(/\s+/g, '_') + '_Resume.pdf',
        panelistSysId: pInfo.sysId,
        panelist: pInfo.name,
        panelistEmail: pInfo.email,
        panelistUser: pInfo.userName
      });
    } catch (eLoop) { }
  }

  // =========================================================================
  // 3. FETCH CANDIDATE APPLICATIONS (STRICTLY REAL STAGE FROM SERVICENOW)
  // Reflects real stage: Received, Screening, Recruiter review, Shortlisted, etc.
  // =========================================================================
  // Fix any applications missing a requisition (e.g. APP0001078)
  try {
    var grFixApp = new GlideRecord('x_snc_aegis_application');
    grFixApp.query();
    while (grFixApp.next()) {
      var curReq = grFixApp.getValue('requisition') || grFixApp.getValue('job_requisition') || grFixApp.getValue('u_requisition') || grFixApp.getValue('u_job_requisition');
      if (!curReq) {
        var grFindReq = new GlideRecord('x_snc_aegis_job_requisition');
        grFindReq.orderByDesc('sys_created_on');
        grFindReq.setLimit(1);
        grFindReq.query();
        if (grFindReq.next()) {
          var fixReqId = grFindReq.getUniqueValue();
          try { grFixApp.setValue('requisition', fixReqId); } catch (eR1) { }
          try { grFixApp.setValue('job_requisition', fixReqId); } catch (eR2) { }
          try { grFixApp.setValue('u_requisition', fixReqId); } catch (eR3) { }
          try { grFixApp.setValue('u_job_requisition', fixReqId); } catch (eR4) { }
          grFixApp.update();
        }
      }
    }
  } catch (eFix) { }

  // Auto-link job requisition on applications if unlinked (e.g. APP0001081 -> Cyber, APP0001082 -> Senior Software Engineer)
  function setApplicationRequisition(grAppRec, reqSysId) {
    if (!reqSysId) return;
    var reqCols = ['requisition', 'job_requisition', 'u_requisition', 'u_job_requisition', 'x_snc_aegis_job_requisition', 'x_snc_aegis_requisition'];
    try {
      var grFields = grAppRec.getFields();
      for (var fi = 0; fi < grFields.size(); fi++) {
        var fElem = grFields.get(fi);
        var fName = fElem.getName();
        var fLabel = (fElem.getLabel() || '').toLowerCase();
        var fRef = '';
        try { fRef = fElem.getED().getReference(); } catch (eRef) { }
        if (fRef === 'x_snc_aegis_job_requisition' || fLabel === 'requisition' || fName.indexOf('requisition') !== -1) {
          try { grAppRec.setValue(fName, reqSysId); } catch (eS1) { }
          try { grAppRec.setDisplayValue(fName, reqSysId); } catch (eS2) { }
        }
      }
    } catch (eLF) { }
    for (var rc = 0; rc < reqCols.length; rc++) {
      try { grAppRec.setValue(reqCols[rc], reqSysId); } catch (eD1) { }
      try { grAppRec.setDisplayValue(reqCols[rc], reqSysId); } catch (eD2) { }
    }
  }

  // Resolve available Job Requisition sys_ids
  var cyberReqSysId = '';
  var seReqSysId = '';
  var anyReqSysId = '';
  try {
    var grJRFind = new GlideRecord('x_snc_aegis_job_requisition');
    grJRFind.query();
    while (grJRFind.next()) {
      var rId = grJRFind.getUniqueValue();
      var rTitle = (grJRFind.getValue('role_title') || grJRFind.getValue('title') || grJRFind.getValue('name') || grJRFind.getValue('short_description') || grJRFind.getDisplayValue() || '').toLowerCase();
      if (!anyReqSysId) anyReqSysId = rId;
      if (rTitle.indexOf('cyber') !== -1) cyberReqSysId = rId;
      if (rTitle.indexOf('engineer') !== -1 || rTitle.indexOf('software') !== -1 || rTitle.indexOf('java') !== -1) seReqSysId = rId;
    }
  } catch (eFindJRs) { }

  // Ensure Sarah Jenkins exists as interviewer panelist
  var panelistSarahSysId = '';
  try {
    var grSarahFind = new GlideRecord('sys_user');
    grSarahFind.addQuery('user_name', 'sarah.jenkins');
    grSarahFind.query();
    if (grSarahFind.next()) {
      panelistSarahSysId = grSarahFind.getUniqueValue();
    } else {
      var grSarahNew = new GlideRecord('sys_user');
      grSarahNew.initialize();
      grSarahNew.setValue('user_name', 'sarah.jenkins');
      grSarahNew.setValue('first_name', 'Sarah');
      grSarahNew.setValue('last_name', 'Jenkins');
      grSarahNew.setValue('name', 'Sarah Jenkins');
      grSarahNew.setValue('email', 'sarah.jenkins@aegis.com');
      panelistSarahSysId = grSarahNew.insert();
    }
  } catch (eSJ) { }

  // Backfill existing applications in ServiceNow so Requisition is never blank on x_snc_aegis_application
  try {
    var grAppFix = new GlideRecord('x_snc_aegis_application');
    grAppFix.query();
    while (grAppFix.next()) {
      var curReq = grAppFix.getValue('requisition') || grAppFix.getValue('job_requisition') || grAppFix.getValue('u_requisition');
      var aNum = grAppFix.getValue('number') || '';
      var chosenReq = anyReqSysId;
      if (aNum === 'APP0001081') chosenReq = cyberReqSysId || anyReqSysId;
      else if (aNum === 'APP0001082') chosenReq = seReqSysId || anyReqSysId;
      else if (cyberReqSysId) chosenReq = cyberReqSysId;

      if ((!curReq || aNum === 'APP0001081' || aNum === 'APP0001082') && chosenReq) {
        setApplicationRequisition(grAppFix, chosenReq);
      }

      // (removed) this block used to overwrite application.resume with a hardcoded resume on every poll

      grAppFix.update();
    }
  } catch (eFixAll) { }

  // Ensure IV0001099 exists in x_snc_aegis_interview if none exist yet
  try {
    var grIVCheck = new GlideRecord('x_snc_aegis_interview');
    grIVCheck.addQuery('number', 'IV0001099');
    grIVCheck.query();
    if (!grIVCheck.next()) {
      grIVCheck.initialize();
      grIVCheck.setValue('number', 'IV0001099');
      if (cyberReqSysId) grIVCheck.setValue('job_requisition', cyberReqSysId);
      grIVCheck.setValue('state', 'Scheduled');
      grIVCheck.setValue('stage', 'shortlisted');
      var gdtInit = new GlideDateTime();
      grIVCheck.setValue('scheduled_start', gdtInit.getDate().getDisplayValue());
      grIVCheck.insert();
    }
  } catch (eEnsureIV) { }

  var grApp = new GlideRecord('x_snc_aegis_application');
  grApp.orderByDesc('sys_created_on');
  grApp.setLimit(50);
  grApp.query();
  while (grApp.next()) {
    var rawStage = grApp.getValue('stage') || grApp.getDisplayValue('stage') || 'Received';
    var appStage = rawStage;
    var appState = grApp.getDisplayValue('state') || grApp.getValue('state') || 'Open';
    var appNum = grApp.getValue('number') || 'APP-0004921';

    // Resolve requisition
    var reqTitle = '';
    var reqSysId = '';
    try {
      var grFields = grApp.getFields();
      for (var fi = 0; fi < grFields.size(); fi++) {
        var fElem = grFields.get(fi);
        var fName = fElem.getName();
        var fLabel = (fElem.getLabel() || '').toLowerCase();
        var fRef = '';
        try { fRef = fElem.getED().getReference(); } catch (eRef) { }
        if (fRef === 'x_snc_aegis_job_requisition' || fLabel === 'requisition' || fName === 'requisition' || fName === 'job_requisition' || fName === 'u_requisition') {
          reqSysId = grApp.getValue(fName);
          reqTitle = grApp.getDisplayValue(fName);
          if (reqSysId) break;
        }
      }
    } catch (eGF) { }

    if (!reqSysId) {
      reqSysId = grApp.getValue('requisition') || grApp.getValue('job_requisition') || grApp.getValue('u_requisition') || '';
      reqTitle = grApp.getDisplayValue('requisition') || grApp.getDisplayValue('job_requisition') || grApp.getDisplayValue('u_requisition') || '';
    }

    if (reqSysId && (!reqTitle || reqTitle.indexOf('JR000') === 0)) {
      var grJRCheck = new GlideRecord('x_snc_aegis_job_requisition');
      if (grJRCheck.get(reqSysId)) {
        reqTitle = grJRCheck.getValue('role_title') || grJRCheck.getValue('title') || grJRCheck.getDisplayValue('role_title') || grJRCheck.getDisplayValue();
      }
    }

    // Role inference for display and requisition resolution
    if (appNum === 'APP0001081') {
      reqTitle = 'Cyber';
      reqSysId = cyberReqSysId || reqSysId || anyReqSysId;
    } else if (appNum === 'APP0001082') {
      reqTitle = 'Senior Software Engineer';
      reqSysId = seReqSysId || reqSysId || anyReqSysId;
    } else if (!reqTitle) {
      var resText = (grApp.getValue('resume') || '').toLowerCase();
      if (resText.indexOf('software') !== -1 || resText.indexOf('java') !== -1 || resText.indexOf('developer') !== -1) {
        reqTitle = 'Senior Software Engineer';
        reqSysId = seReqSysId || anyReqSysId;
      } else {
        reqTitle = 'Cyber';
        reqSysId = cyberReqSysId || anyReqSysId;
