    }

    if (!reqSysId) {
      if (reqTitle.toLowerCase().indexOf('cyber') !== -1) reqSysId = cyberReqSysId || anyReqSysId;
      else if (reqTitle.toLowerCase().indexOf('software') !== -1 || reqTitle.toLowerCase().indexOf('engineer') !== -1) reqSysId = seReqSysId || anyReqSysId;
