    var isWithdrawn = grApp.getValue('withdrawn') == '1' || grApp.getValue('withdrawn') === true || (rawStage.toLowerCase() === 'closed' && (grApp.getValue('withdrawn') == '1' || grApp.getValue('withdrawn') === true));
    var rejectedAt = grApp.getDisplayValue('rejected_at') ||
