    // If stage is rejected or rejected_at has a value
    var isActuallyRejected = (rawStage.toLowerCase().indexOf('reject') !== -1) ||
      (!!rejectedAt && rejectedAt.toLowerCase() !== 'none' && rejectedAt.toLowerCase() !== 'false');

    var appDeadline = '';
    try {
      if (reqSysId) {
