  }

  // =========================================================================
  // 4. ACTION DISPATCHER (FROM CLIENT CONTROLLER c.server.update)
  // =========================================================================
  if (input) {

    // ACTION: REAL-TIME DATA FETCH / LIVE UPDATES
    // Immediately returns the latest database state without modification
    if (input.action === 'get_live_updates') {
      data.liveSuccess = true;
      return;
    }

    // ACTION: CANDIDATE REGISTRATION
    // Saves into sys_user, assigns the 'candidate' role via sys_user_has_role, and creates x_snc_aegis_candidate
    // HELPER: PASSWORD CONSTRAINTS CHECK
    function meetsPasswordConstraints(pwd) {
      if (!pwd || pwd.length < 8) return false;
      var hasUpper = /[A-Z]/.test(pwd);
      var hasLower = /[a-z]/.test(pwd);
      var hasDigit = /[0-9]/.test(pwd);
      var hasSpecial = /[^A-Za-z0-9]/.test(pwd);
      return hasUpper && hasLower && hasDigit && hasSpecial;
    }

