    // Creates sys_user with user_name as 'firstname.lastname' (and .1, .2 collision resolution)
    // Enforces password constraints and assigns 'candidate' role via sys_user_has_role
    if (input.action === 'register_candidate') {
      try {
        if (!meetsPasswordConstraints(input.password)) {
          data.regSuccess = false;
          data.error = "Password must be at least 8 characters and contain at least one uppercase letter, one lowercase letter, one number, and one special character.";
          return;
