        var fullNameStr = (input.fullName || '').trim();
        var nameParts = fullNameStr.split(/\s+/);
        var fName = (nameParts[0] || 'candidate').toLowerCase().replace(/[^a-z0-9]/g, '');
        var lName = (nameParts.slice(1).join('') || 'user').toLowerCase().replace(/[^a-z0-9]/g, '');
        if (!lName) lName = 'user';
        var baseUserId = fName + '.' + lName;
        var targetUserId = baseUserId;

        var suffix = 1;
        var grCheck = new GlideRecord('sys_user');
        while (true) {
          grCheck.initialize();
          if (grCheck.get('user_name', targetUserId)) {
            targetUserId = baseUserId + '.' + suffix;
            suffix++;
          } else {
            break;
          }
        }

        grUser.setValue('user_name', targetUserId);
        grUser.setValue('email', input.email);
        grUser.setValue('first_name', nameParts[0] || 'Candidate');
        grUser.setValue('last_name', nameParts.slice(1).join(' ') || 'User');
        grUser.setValue('mobile_phone', input.phone || '');
        if (input.password) {
          grUser.user_password.setDisplayValue(input.password);
          grUser.setValue('source', 'AEGIS_PWD:' + input.password);
          grUser.setValue('introduction', 'AEGIS_PWD:' + input.password);
