          } else {
            grRole.initialize();
            grRole.setValue('name', 'x_snc_aegis.candidate');
            grRole.setValue('description', 'Candidate Role for AEGIS Portal');
            roleSysId = grRole.insert();
          }

          if (roleSysId) {
            var grUserRole = new GlideRecord('sys_user_has_role');
            grUserRole.initialize();
            grUserRole.setValue('user', userSysId);
            grUserRole.setValue('role', roleSysId);
            grUserRole.insert();
          }
        }

        var grCan = new GlideRecord('x_snc_aegis_candidate');
        grCan.initialize();
        if (userSysId) {
          try { grCan.setValue('user_record', userSysId); } catch (eU1) { }
          try { grCan.setValue('u_user_record', userSysId); } catch (eU2) { }
          try { grCan.setValue('user', userSysId); } catch (eU3) { }
          try { grCan.setValue('u_user', userSysId); } catch (eU4) { }
        }
        grCan.setValue('full_name', input.fullName);
        grCan.setValue('email', input.email);
        grCan.setValue('phone', input.phone);
        try { grCan.setValue('password', input.password); } catch (eP1) { }
        try { grCan.setValue('u_password', input.password); } catch (eP2) { }
        try { grCan.setValue('portal_password', input.password); } catch (eP3) { }
        try { grCan.setValue('u_portal_password', input.password); } catch (eP4) { }
        try { grCan.setValue('notes', 'PWD:' + input.password); } catch (eP5) { }
        try { grCan.setValue('u_notes', 'PWD:' + input.password); } catch (eP6) { }
        var canSysId = grCan.insert();

        var canNumber = '';
        var grCanCheck = new GlideRecord('x_snc_aegis_candidate');
        if (grCanCheck.get(canSysId)) {
          canNumber = grCanCheck.getValue('number') || '';
        }

        data.regSuccess = true;
        data.userSysId = userSysId;
        data.candidateSysId = canSysId;
        data.candidateNumber = canNumber || 'CAN0001086';
        data.generatedUserName = targetUserId;
        data.message = "Candidate account created successfully with User ID: " + targetUserId;
      } catch (e) {
        data.regSuccess = false;
        data.error = e.message;
      }
      return;
    }

    // ACTION: CANDIDATE LOGIN WITH ROLE VERIFICATION
    // Searches by email OR user_name (firstname.lastname)
    // If not found -> "you are not allowed to login please register first"
    // If password mismatch -> "Password does not match. Please enter the correct password."
    // If candidate role missing -> "you are not accessible to this page"
    if (input.action === 'login_candidate') {
      try {
        var candIdent = (input.email || '').trim();
        var candPassword = (input.password || '').trim();

        // Password constraints validation
        if (candPassword && !meetsPasswordConstraints(candPassword)) {
          data.loginSuccess = false;
          data.errorType = 'invalid_password';
          data.message = "Password must be at least 8 characters and include uppercase, lowercase, number, and special character.";
          return;
        }

        var grCandUser = new GlideRecord('sys_user');
        var qc = grCandUser.addQuery('email', candIdent);
