        }

        // 2. Validate Password against sys_user source/preferences and candidate record
        var storedCandPwd = '';

        // Check sys_user source and introduction tokens
        if (userFound) {
          var uCandSource = grCandUser.getValue('source') || '';
          if (uCandSource.indexOf('AEGIS_PWD:') !== -1) {
            storedCandPwd = uCandSource.replace('AEGIS_PWD:', '').trim();
          } else if (uCandSource && uCandSource.length >= 8) {
