          } catch (eUpUser) { }
          // (removed: sys_user_preference is a global table - cross-scope access refused)
        }

        // 3. Candidate role check (safe string conversion, checks candidate / x_snc_aegis.candidate)
        var hasCandidateRole = false;
        if (userFound) {
          var uSysId = grCandUser.getUniqueValue();
          var grURole = new GlideRecord('sys_user_has_role');
          grURole.addQuery('user', uSysId);
          grURole.query();
          while (grURole.next()) {
            var rStr = '';
            try {
              if (grURole.role && grURole.role.name) {
                rStr = grURole.role.name.toString();
              } else {
                rStr = grURole.getDisplayValue('role') || '';
              }
            } catch (eR) { }
            rStr = (rStr + '').toLowerCase();
            if (rStr.indexOf('candidate') !== -1) {
              hasCandidateRole = true;
              break;
            }
          }
        }

        if (candProfileFound) {
          hasCandidateRole = true;
        }

        if (!hasCandidateRole) {
          data.loginSuccess = false;
          data.errorType = 'no_access';
          data.message = "you are not accessible to this page";
          return;
        }

        // Ensure x_snc_aegis_candidate record exists and is linked to sys_user
        var resolvedCandSysId = candProfileFound ? grCandProfile.getUniqueValue() : '';
        if (userFound) {
          var uSysId = grCandUser.getUniqueValue();
          var uEmail = grCandUser.getValue('email') || candIdent;
          var uFullName = grCandUser.getDisplayValue('name') || 'Candidate';

          if (!resolvedCandSysId) {
            var grCanSync = new GlideRecord('x_snc_aegis_candidate');
