              try { grCanUpExisting.setValue('u_user_record', uSysId); } catch (eU2) { }
              try { grCanUpExisting.setValue('user', uSysId); } catch (eU3) { }
              try { grCanUpExisting.setValue('u_user', uSysId); } catch (eU4) { }
